func valueThread(p unsafe.Pointer, c int32) any {
	r := (*conversation.Thread)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.UserID)
	case 4:
		return string(r.AgentDefinitionID)
	case 5:
		if r.Title == "" {
			return nil
		}
		return r.Title
	case 6:
		return string(r.Status)
	case 7:
		return r.LastMessageAt
	case 8:
		return r.LastReadAt
	case 9:
		if r.PreferredProviderID == "" {
			return nil
		}
		return string(r.PreferredProviderID)
	case 10:
		return string(r.Origin)
	case 11:
		return r.Pinned
	case 12:
		if r.SubjectType == "" {
			return nil
		}
		return string(r.SubjectType)
	case 13:
		if r.SubjectID == "" {
			return nil
		}
		return string(r.SubjectID)
	case 14:
		if r.SnoozedUntil == nil {
			return nil
		}
		return *r.SnoozedUntil
	case 15:
		if r.SnoozeAnchor == "" {
			return nil
		}
		return string(r.SnoozeAnchor)
	case 16:
		if r.SnoozeStopID == "" {
			return nil
		}
		return string(r.SnoozeStopID)
	case 17:
		if r.PinnedFacts == nil {
			return nil
		}
		return r.PinnedFacts
	case 18:
		if r.WorkingSet == nil {
			return nil
		}
		return r.WorkingSet
	case 19:
		if r.ContextUsage == nil {
			return nil
		}
		return *r.ContextUsage
	case 20:
		return r.AutoCompactOff
	case 21:
		if r.HandedFromThreadID == "" {
			return nil
		}
		return string(r.HandedFromThreadID)
	case 22:
		if r.Taint == nil {
			return nil
		}
		return *r.Taint
	case 23:
		if r.TaintedAt == nil {
			return nil
		}
		return *r.TaintedAt
	case 24:
		return r.Version
	case 25:
		return r.CreatedAt
	case 26:
		return r.UpdatedAt
	}
	return nil
}

func attachThread(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*conversation.Thread)(p)
	switch rel {
	case 0:
		r.User = (*tenant.User)(child)
	}
}

func beforeCreateThread(ctx context.Context, p unsafe.Pointer) error {
	return (*conversation.Thread)(p).BeforeCreate(ctx)
}

func init() {
	messagesTable.Relations[0].Target = ThreadsSchema()
	queuedMessagesTable.Relations[0].Target = tenantdb.UsersSchema()
	queuedMessagesTable.Relations[1].Target = ThreadsSchema()
	threadsTable.Relations[0].Target = tenantdb.UsersSchema()
}

